import csv

# Read CATALOG_CSV for timeseries IDs
with open(CATALOG_CSV, mode='r') as cat_file:
    csv_reader = csv.DictReader(cat_file)
    electric_power_id = None
    occupancy_id = None
    for row in csv_reader:
        if row['point_class'] == 'brick:Electric_Power':
            electric_power_id = row['timeseries_id']
        if row['point_class'] == 'brick:Occupancy':
            occupancy_id = row['timeseries_id']

# Read VALUES_CSV for values at the specific time
with open(VALUES_CSV, mode='r') as val_file:
    csv_reader = csv.DictReader(val_file)
    values = list(csv_reader)

# Find the values at the specific time
lighting_power_value = next((float(row['value']) for row in values if row['timeseries_id'] == electric_power_id and row['timestamp'] == '2018-07-07 02:00'), None)
occupancy_value = next((int(row['value']) for row in values if row['timeseries_id'] == occupancy_id and row['timestamp'] == '2018-07-07 02:00'), None)

if lighting_power_value is not None and occupancy_value is not None:
    answer = {"value": lighting_power_value > 1 and occupancy_value == 0}
else:
    answer = {"abstain": True, "needed_streams": "Electric_Power and Occupancy timeseries IDs for the zone Perimeter_top_ZN_4"}

print(answer)
